 "content": "def transform(grid):
    """Extend full 3x3 marker blocks along their central row and column."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    blocks = []
    # Find monochromatic 3x3 markers.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[rr][cc] == color
                   for rr in range(r, r + 3)
                   for cc in range(c, c + 3)):
                item = (r + 1, c + 1, color)
                if item not in blocks:
                    blocks.append(item)
    # Rays overwrite any incidental cells they pass through.
    for r, c, color in blocks:
        for x in range(w):
            out[r][x] = color
        for y in range(h):
            out[y][c] = color
    # Where rays from distinct markers cross, leave a one-cell gap.
    for r1, c1, color1 in blocks:
        for r2, c2, color2 in blocks:
            if color1 != color2:
                out[r1][c2] = 0
                out[r2][c1] = 0
    return out
